    import random
    import time

    LANGUAGE_WRAPPER = 'Consider a biased simple random walk on the integers starting at 0: at each step it moves +1 with probability p and −1 with probability 1−p. Fix integers {n}≥1 and {m}≥1, and endpoints {a}≥0 and {b}≥0 such that n+a and m+b are even. Let X be the probability that after n steps the walk is exactly at position a and has stayed nonnegative at all intermediate times (i.e., its running position is always ≥0 up to step n). Let Y be the analogous probability for m steps and endpoint b. For a given lower bound {p0} with 1/2<{p0}<1, determine the minimal integer L such that for all p in [{p0},1), the inequality X > (1−p)^{L} · Y holds.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

